#include "femgpu/TopoSpmv.h"

#include "fem_spmv_spv.h"  // generated by cmake/EmbedSpirv.cmake

#include <cstring>

namespace gpu {

namespace {

// Must match the push-constant block in fem_spmv.comp.
struct SpmvPush {
  uint32_t nElems;
  uint32_t groupsX;
};

// The Vulkan spec only guarantees 65535 workgroups per dimension, so the
// one-workgroup-per-element dispatch goes 2D past that.
constexpr uint32_t kMaxGroupsX = 32768;

}  // namespace

std::unique_ptr<TopoSpmv> TopoSpmv::Create(ComputeContext& ctx,
                                           const SpmvSystem& sys,
                                           std::string* error) {
  auto fail = [&](const std::string& m) -> std::unique_ptr<TopoSpmv> {
    if (error) *error = m;
    return nullptr;
  };
  if (sys.nFree <= 0 || sys.nElems <= 0) return fail("empty SpMV system");
  if (sys.dof.size() != static_cast<size_t>(sys.nElems) * 30 ||
      sys.ke.size() != static_cast<size_t>(sys.nElems) * 900)
    return fail("SpMV system arrays have the wrong size");

  std::unique_ptr<TopoSpmv> s(new TopoSpmv(ctx));
  s->m_nFree = sys.nFree;
  s->m_nElems = sys.nElems;

  if (!ctx.CreatePipeline(k_fem_spmv_spv, k_fem_spmv_spv_size, 5,
                          sizeof(SpmvPush), s->m_pipeline, error))
    return nullptr;

  auto make = [&](Buffer& b, VkDeviceSize size) {
    return ctx.CreateBuffer(size, b, error);
  };
  if (!make(s->m_dof, sys.dof.size() * sizeof(int32_t))) return nullptr;
  if (!make(s->m_ke, sys.ke.size() * sizeof(float))) return nullptr;
  if (!make(s->m_scale, sys.nElems * sizeof(float))) return nullptr;
  if (!make(s->m_p, sys.nFree * sizeof(float))) return nullptr;
  if (!make(s->m_ap, sys.nFree * sizeof(float))) return nullptr;

  std::memcpy(s->m_dof.mapped, sys.dof.data(), s->m_dof.size);
  std::memcpy(s->m_ke.mapped, sys.ke.data(), s->m_ke.size);
  // Scales default to 1 (full stiffness) until SetScales.
  {
    float* sc = static_cast<float*>(s->m_scale.mapped);
    for (int e = 0; e < sys.nElems; ++e) sc[e] = 1.0f;
  }
  return s;
}

TopoSpmv::~TopoSpmv() {
  m_ctx.Destroy(m_dof);
  m_ctx.Destroy(m_ke);
  m_ctx.Destroy(m_scale);
  m_ctx.Destroy(m_p);
  m_ctx.Destroy(m_ap);
  m_ctx.Destroy(m_pipeline);
}

bool TopoSpmv::SetScales(const std::vector<float>& scales, std::string* error) {
  if (scales.size() != static_cast<size_t>(m_nElems)) {
    if (error) *error = "scale count != element count";
    return false;
  }
  std::memcpy(m_scale.mapped, scales.data(), m_scale.size);
  return true;
}

bool TopoSpmv::Apply(const std::vector<float>& p, std::vector<float>& Ap,
                     std::string* error) {
  if (p.size() != static_cast<size_t>(m_nFree)) {
    if (error) *error = "p size != nFree";
    return false;
  }
  std::memcpy(m_p.mapped, p.data(), m_p.size);
  std::memset(m_ap.mapped, 0, m_ap.size);  // scatter target starts at zero

  const uint32_t n = static_cast<uint32_t>(m_nElems);
  const uint32_t gx = n < kMaxGroupsX ? n : kMaxGroupsX;
  const uint32_t gy = (n + gx - 1) / gx;
  SpmvPush push{n, gx};
  if (!m_ctx.Dispatch(m_pipeline, {&m_dof, &m_ke, &m_scale, &m_p, &m_ap}, &push,
                      sizeof(push), gx, gy, error))
    return false;

  Ap.resize(m_nFree);
  std::memcpy(Ap.data(), m_ap.mapped, m_ap.size);
  return true;
}

}  // namespace gpu
